mapper.select:
select visible.id, visible.display_name, visible.remark

     , visible.sort_at
from (
    select c.id, c.display_name, c.remark,
           coalesce(
               (select max(m.occurred_at)
                from contact_identities ci
                join conversations cv on cv.contact_identity_id = ci.id
                join messages m on m.conversation_id = cv.id
                where ci.contact_id = c.id
                  and (
                      cv.assigned_user_id = #{userId}
                      or exists (select 1 from team_members tm
                                 where tm.team_id = cv.assigned_team_id
                                   and tm.user_id = #{userId})
                      or exists (select 1 from conversation_access_grants g
                                 where g.conversation_id = cv.id
                                   and g.user_id = #{userId}
                                   and g.revoked_at is null
                                   and (g.expires_at is null or g.expires_at > now()))
                  )
               ),
               c.updated_at
           ) as sort_at
    from contacts c
    where c.deleted_at is null
      and c.status <> 'merged'
      and (
          c.created_by = #{userId}
          or exists (
              select 1 from contact_identities ci
              join conversations cv on cv.contact_identity_id = ci.id
              where ci.contact_id = c.id
                and (
                    cv.assigned_user_id = #{userId}
                    or exists (
                        select 1 from team_members tm
                        where tm.team_id = cv.assigned_team_id
                          and tm.user_id = #{userId}
                    )
                    or exists (
                        select 1 from conversation_access_grants g
                        where g.conversation_id = cv.id
                          and g.user_id = #{userId}
                          and g.revoked_at is null
                          and (g.expires_at is null or g.expires_at > now())
                    )
                )
          )
      )

      and (c.display_name ilike '%' || #{search} || '%'
           or coalesce(c.remark, '') ilike '%' || #{search} || '%')

) visible
where 1 = 1

  and (visible.sort_at < #{beforeLastMessageAt}
       or (visible.sort_at = #{beforeLastMessageAt} and visible.id < #{beforeId}))

order by visible.sort_at desc, visible.id desc
limit ${page.size}
